import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { vendorService } from '../../services/vendorService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage, getStatusText, getStatusColor, formatDateTime } from '../../utils/helpers';

const VendorDashboard = () => {
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await vendorService.getDashboardData();
      setDashboardData(response.data);
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LoadingSpinner message="Loading your dashboard..." />;
  }

  if (error) {
    return (
      <div className="dashboard-page">
        <div className="container">
          <div className="error-container">
            <div className="error-message">
              <h2>Error Loading Dashboard</h2>
              <p>{error}</p>
              <button onClick={loadDashboardData} className="btn btn-primary">
                Try Again
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const hasProfile = dashboardData?.profile;
  const applications = dashboardData?.applications || [];

  return (
    <div className="dashboard-page vendor-dashboard">
      <div className="container">
        <div className="dashboard-header">
          <h1>Vendor Dashboard</h1>
          <p>Manage your food truck profile and applications</p>
        </div>

        {/* Profile Status Card */}
        <div className="dashboard-cards">
          <div className="dashboard-card profile-card">
            <div className="card-header">
              <h3>Profile Status</h3>
            </div>
            <div className="card-content">
              {hasProfile ? (
                <div className="profile-complete">
                  <div className="status-indicator success">✓</div>
                  <div className="status-info">
                    <h4>{dashboardData.profile.name}</h4>
                    <p>Profile Complete</p>
                    <p className="cuisine">{dashboardData.profile.cuisineSpecialties}</p>
                    <p className="region">{dashboardData.profile.operatingRegion}</p>
                  </div>
                  <Link to="/vendor-profile" className="btn btn-outline">
                    Edit Profile
                  </Link>
                </div>
              ) : (
                <div className="profile-incomplete">
                  <div className="status-indicator warning">!</div>
                  <div className="status-info">
                    <h4>Profile Incomplete</h4>
                    <p>Complete your profile to start applying for licenses</p>
                  </div>
                  <Link to="/vendor-profile" className="btn btn-primary">
                    Complete Profile
                  </Link>
                </div>
              )}
            </div>
          </div>

          {/* Applications Card */}
          <div className="dashboard-card applications-card">
            <div className="card-header">
              <h3>Applications</h3>
              <span className="count-badge">{applications.length}</span>
            </div>
            <div className="card-content">
              {applications.length > 0 ? (
                <div className="applications-summary">
                  <div className="summary-stats">
                    <div className="stat">
                      <span className="stat-number">
                        {applications.filter(app => app.status === 'SUBMITTED' || app.status === 'UNDER_REVIEW').length}
                      </span>
                      <span className="stat-label">Pending</span>
                    </div>
                    <div className="stat">
                      <span className="stat-number">
                        {applications.filter(app => app.status === 'APPROVED' || app.status === 'LICENSED').length}
                      </span>
                      <span className="stat-label">Approved</span>
                    </div>
                  </div>
                  <Link to="/application-status" className="btn btn-outline">
                    View All Applications
                  </Link>
                </div>
              ) : (
                <div className="no-applications">
                  <p>No applications submitted yet</p>
                  {hasProfile ? (
                    <Link to="/application" className="btn btn-primary">
                      Create Application
                    </Link>
                  ) : (
                    <p className="note">Complete your profile first to create applications</p>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Quick Actions */}
        <div className="quick-actions">
          <h3>Quick Actions</h3>
          <div className="actions-grid">
            <Link to="/vendor-profile" className="action-card">
              <div className="action-icon">👤</div>
              <h4>Manage Profile</h4>
              <p>Update your business information and details</p>
            </Link>

            {hasProfile && (
              <Link to="/application" className="action-card">
                <div className="action-icon">📄</div>
                <h4>New Application</h4>
                <p>Submit a new license application</p>
              </Link>
            )}

            <Link to="/application-status" className="action-card">
              <div className="action-icon">📊</div>
              <h4>Track Applications</h4>
              <p>Monitor the status of your applications</p>
            </Link>
          </div>
        </div>

        {/* Recent Applications */}
        {applications.length > 0 && (
          <div className="recent-applications">
            <div className="section-header">
              <h3>Recent Applications</h3>
              <Link to="/application-status">View All</Link>
            </div>
            
            <div className="applications-list">
              {applications.slice(0, 3).map((application) => (
                <div key={application.id} className="application-item">
                  <div className="application-info">
                    <div className="application-id">Application #{application.id}</div>
                    <div className="application-date">
                      Created: {formatDateTime(application.createdAt)}
                    </div>
                    {application.submittedAt && (
                      <div className="application-date">
                        Submitted: {formatDateTime(application.submittedAt)}
                      </div>
                    )}
                  </div>
                  <div className={`status-badge ${getStatusColor(application.status)}`}>
                    {getStatusText(application.status)}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default VendorDashboard;
